struct ScopedPrivilegeDrop {                     // RAII: the drop cannot be skipped
  ScopedPrivilegeDrop(uid_t uid, gid_t gid) {
    if (setgroups(0, nullptr) || setresgid(-1, gid, gid) || setresuid(-1, uid, uid))
      throw std::system_error(errno, std::generic_category(), "privilege drop");
  }
};
struct ReadOnlyRepo {                            // narrowest interface, no writes
  virtual std::string load(std::string_view id) const = 0;
protected:
  ~ReadOnlyRepo() = default;                     // no polymorphic delete
};
void handle(Request const& r, ReadOnlyRepo const& repo);
